LoginComponent
LoginComponent performs various tasks required to properly handle the user's login
process; consequently, any Angular Component and/or .NET Core Controller that
wants to restrict its access to authenticated users should perform an HTTP redirect to
this Component's route; as we can see by looking at the source code of the
Component's defining method, if the incoming request provides a returnUrl query
parameter, the Component will redirect the user back to it after performing the login:
//...
private async login(returnUrl: string): Promise<void> {
const state: INavigationState = { returnUrl };
const result = await this.authorizeService.signIn(state);
this.message.next(undefined);
switch (result.status) {
case AuthenticationResultStatus.Redirect:
break;
case AuthenticationResultStatus.Success:
await this.navigateToReturnUrl(returnUrl);
break;
case AuthenticationResultStatus.Fail:
await this.router.navigate(
ApplicationPaths.LoginFailedPathComponents, {
queryParams: { [QueryParameterNames.Message]: result.message }
});
break;
default:
throw new Error(`Invalid status result ${(result as
any).status}.`);
}
}
// ...
